Lemma chk1 fx R M cur k :
  getr R (reg 8) = Z_to_bv 64 cur -> getr R (reg 20) = Z_to_bv 64 SBL -> 0 <= cur < 2 ^ 47 ->
  rdn RSEGS M (Z_to_bv 64 (cur / 8 + SBL)) 1%nat = Some [Z_to_bv 8 k] ->
  (k = 0 \/ (1 <= k <= 7 /\ cur mod 8 < k)) ->
  exists R', msteps RSEGS (mst fx R 0xac1c4 M) (mst fx R' 0xac1d4 M)
    /\ (forall j, j <> 10%nat -> j <> 11%nat -> (j < 32)%nat -> getr R' (reg j) = getr R (reg j)).
